head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > radioLabelPosition]<br/>inputType='radio' 인 Column 에 라벨 텍스트가 표시될 위치를 설정합니다.",
    "validation" : [
        "Column 의 radioLabel, radioLabelColumn, radioLabelFormatter 속성으로 라벨 텍스트가 표시되는 경우 동작합니다.",
        "left 설정 시, 라벨 텍스트를 라디오 버튼 왼쪽에 표시합니다.",
        "right 설정 시, 라벨 텍스트를 라디오 버튼 오른쪽에 표시합니다.",
        "미설정 시, 라벨 텍스트를 라디오 버튼 오른쪽에 표시합니다.",
    ]
}



scwin.onpageload = async function () {
    // Global DataList(gdl_boolean 등) 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (검증 대상 속성만 의미 있는 값으로 초기 선택)
    con_radioLabelPosition.setValue("left");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - Body 의 sel Column(inputType=radio, Body Column 인덱스 3) 에만 con 값 적용
//  - 라벨 표시 속성(radioLabel / radioLabelColumn / radioLabelFormatter) 은 동작 전제 조건으로만 사용
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 라벨 위치와 라벨 표시 속성은 라디오 Column(선택, Body Column 인덱스 3) 에 설정\n[확인] 재생성 직후 결과창의 라벨 위치와 화면상 라벨-라디오 버튼 좌우 배치"', '', 'label1');

    // 조건 설정 (미설정 옵션은 속성 자체를 넣지 않는다)
    let cPosition = con_radioLabelPosition.getValue();
    let cLabelProp = con_labelProperty.getValue();

    let attrSel = (cPosition === '') ? '' : ' radioLabelPosition="' + cPosition + '"';
    if (cLabelProp === 'radioLabel') {
        attrSel += ' radioLabel="선택"';
    } else if (cLabelProp === 'radioLabelColumn') {
        attrSel += ' radioLabelColumn="name"';
    } else if (cLabelProp === 'radioLabelFormatter') {
        attrSel += ' radioLabelFormatter="scwin.radio_labelFormatter"';
    }

    // dataList 생성
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="price" name="price" dataType="number"></w2:column>';
    strDlt += '<w2:column id="regDate" name="regDate" dataType="text"></w2:column>';
    strDlt += '<w2:column id="sel" name="sel" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "name" : "노트북", "price" : "1250000", "regDate" : "20260105", "sel" : "0" },
        { "name" : "모니터", "price" : "320000", "regDate" : "20260212", "sel" : "1" },
        { "name" : "키보드", "price" : "89000", "regDate" : "20260320", "sel" : "0" },
        { "name" : "마우스", "price" : "45000", "regDate" : "20260418", "sel" : "0" }
    ], false);

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:600px;height:220px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column1" value="상품명"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="column2" value="가격"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="column3" value="등록일"></w2:column>';
    strTarget += '<w2:column width="260" style="" inputType="text" id="column4" value="선택"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="name" value=""></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="price" value="" dataType="number" displayFormat="#,###"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="regDate" value="" displayFormat="####-##-##"></w2:column>';
    strTarget += '<w2:column width="260" style="" inputType="radio" id="sel" value=""' + attrSel + '></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // validation 1 ~ 4 : 재생성 직후 Body 라벨 위치 출력
    setTimeout(function () {
        scwin.printPosition();
    }, 100);
}



// radioLabelFormatter 전제용 사용자 정의 함수 : 상품명 뒤에 '선택' 을 붙여 반환
scwin.radio_labelFormatter = function (row, col, radioLabel) {
    return dlt_bind.getCellData(row, "name") + " 선택";
}



// 셀(td) 안의 라벨과 라디오 버튼 배치 판정 (DOM 순서 + 화면상 x 좌표)
scwin.getPositionInfo = function (td) {
    let input = td ? td.querySelector("input[type='radio']") : null;
    let label = td ? td.querySelector("label") : null;
    if (!input || !label) {
        return { text : "", pos : input ? "라벨 없음" : "라디오 버튼 없음" };
    }
    let domLeft = (label.compareDocumentPosition(input) & Node.DOCUMENT_POSITION_FOLLOWING) ? true : false;
    let labelX = Math.round(label.getBoundingClientRect().left);
    let inputX = Math.round(input.getBoundingClientRect().left);
    let screenLeft = labelX < inputX;
    let strPos = (domLeft === screenLeft) ? (screenLeft ? "라디오 버튼 왼쪽" : "라디오 버튼 오른쪽") : "DOM 순서와 화면 위치 불일치";
    return {
        text : "'" + label.textContent + "'",
        pos : strPos + " (DOM " + (domLeft ? "label -> input" : "input -> label") + ", 라벨 위치 " + labelX + "px / 라디오 버튼 위치 " + inputX + "px)"
    };
}



// validation 1 ~ 4 : Body 라벨 위치 출력 (모든 행의 배치가 같으면 1줄로 묶고, 다르면 행별로 출력)
scwin.printPosition = function () {
    let arrText = [];
    let arrPos = [];
    for (let i = 0; i < dlt_bind.getRowCount(); i++) {
        let td = document.querySelector("td[id*='" + target1.id + "_cell_" + i + "_3']");
        let info = scwin.getPositionInfo(td);
        arrText.push(info.text);
        arrPos.push(info.pos);
    }
    let samePos = arrPos.every(function (pos) { return pos === arrPos[0]; });
    let strBody = "";
    if (samePos) {
        strBody = (arrText[0] ? arrText.join(", ") + " 모두 " : "모든 행 ") + arrPos[0];
    } else {
        strBody = arrPos.map(function (pos, i) { return i + "행 " + arrText[i] + " " + pos; }).join(" / ");
    }
    wf_body_bottom.getObj("scwin").setReturnValue("라벨 위치 : " + strBody);
}
